template <int N>
struct Factorial {
    // Recursive case: Compiler computes N * Factorial<N-1>::value
    static constexpr int value = N * Factorial<N - 1>::value;
};

template <>
struct Factorial<0> {
    // Base case specialization (Polymorphism)
    static constexpr int value = 1;
};

// All computation occurs during compilation via instantiation
constexpr int result_5 = Factorial<5>::value; // 120

// Template instantiation defines code generation path (polymorphism)
constexpr int result_10 = Factorial<10>::value;
